-- Disposable Mission Control read acceptance fixture, never a production seed.
SELECT gen_random_uuid(),x.email,'Mission Workspace QC',a.password_hash FROM human_accounts a
CROSS JOIN (VALUES ('mission-workspace-admin@example.test'),('mission-workspace-member@example.test')) x(email)
WHERE a.email='qc@example.test';
SELECT id,'20202020-2020-4020-8020-202020202020',CASE WHEN email='mission-workspace-admin@example.test' THEN 'ADMIN' ELSE 'MEMBER' END
FROM human_accounts WHERE email IN ('mission-workspace-admin@example.test','mission-workspace-member@example.test');
SELECT ('20400000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20202020-2020-4020-8020-202020202020',
'20100000-0000-4000-8000-000000000001','20300000-0000-4000-8000-000000000001','Control task '||lpad(n::text,2,'0'),state,
CASE WHEN state IN ('WAITING','BLOCKED') THEN 'Await evidence '||n ELSE NULL END,
CASE WHEN state IN ('WAITING','BLOCKED') THEN TIMESTAMPTZ '2026-02-01 00:00:00+00'+n*interval '1 minute' ELSE NULL END,
CASE WHEN state IN ('WAITING','BLOCKED') THEN 'Control operator' ELSE NULL END,
TIMESTAMPTZ '2026-02-01 00:00:00+00'+n*interval '1 second',now()
FROM (SELECT n,CASE WHEN n<=9 THEN (ARRAY['DRAFT','READY','RUNNING','WAITING','BLOCKED','IN_REVIEW','COMPLETED','FAILED','CANCELLED'])[n] WHEN n%2=0 THEN 'WAITING' ELSE 'BLOCKED' END AS state FROM generate_series(1,31) n) x;
SELECT ('20500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20202020-2020-4020-8020-202020202020',
CASE WHEN n%2=0 THEN NULL ELSE '20300000-0000-4000-8000-000000000001'::uuid END,
CASE WHEN n=25 THEN NULL ELSE '20400000-0000-4000-8000-000000000001'::uuid END,'HUMAN',
(SELECT id FROM human_accounts WHERE email='mission-workspace-admin@example.test'),'CONTROL_TASK_EVENT','PRIVATE_CONTROL_PAYLOAD',
TIMESTAMPTZ '2026-02-01 00:00:00+00'+n*interval '1 second' FROM generate_series(1,25) n;
